    94  int IFileReaderDevice::getNextPackets(RawPacketVector& packetVec, int numOfPacketsToRead)
    95  {
    96          int numOfPacketsRead = 0;
    97
    98          for (; numOfPacketsToRead < 0 || numOfPacketsRead < numOfPacketsToRead; numOfPacketsRead++)
    99          {
   100                  RawPacket* newPacket = new RawPacket();
   101                  bool packetRead = getNextPacket(*newPacket);
   102                  if (packetRead)
   103                  {
   104                          packetVec.pushBack(newPacket);
   105                  }
   106                  else
   107                  {
   108                          delete newPacket;
   109                          break;
   110                  }
   111          }
   112
   113          return numOfPacketsRead;
   114  }
