   122  bool PcapFileReaderDevice::open()
   123  {
   124          m_NumOfPacketsRead = 0;
   125          m_NumOfPacketsNotParsed = 0;
   126
   127          if (m_PcapDescriptor != NULL)
   128          {
   129                  LOG_DEBUG("Pcap descriptor already opened. Nothing to do");
   130                  return true;
   131          }
   132
   133          char errbuf[PCAP_ERRBUF_SIZE];
   134          m_PcapDescriptor = pcap_open_offline(m_FileName, errbuf);
   135          if (m_PcapDescriptor == NULL)
   136          {
   137                  LOG_ERROR("Cannot open file reader device for filename '%s': %s", m_FileName, errbuf);
   138                  m_DeviceOpened = false;
   139                  return false;
   140          }
   141
   142          m_PcapLinkLayerType = static_cast<LinkLayerType>(pcap_datalink(m_PcapDescriptor));
   143
   144          LOG_DEBUG("Successfully opened file reader device for filename '%s'", m_FileName);
   145          m_DeviceOpened = true;
   146          return true;
   147  }
