   157  bool PcapFileReaderDevice::getNextPacket(RawPacket& rawPacket)
   158  {
   159          rawPacket.clear();
   160          if (m_PcapDescriptor == NULL)
   161          {
   162                  LOG_ERROR("File device '%s' not opened", m_FileName);
   163                  return false;
   164          }
   165          pcap_pkthdr pkthdr;
   166          const uint8_t* pPacketData = pcap_next(m_PcapDescriptor, &pkthdr);
   167          if (pPacketData == NULL)
   168          {
   169                  LOG_DEBUG("Packet could not be read. Probably end-of-file");
   170                  return false;
   171          }
   172
   173          uint8_t* pMyPacketData = new uint8_t[pkthdr.caplen];
   174          memcpy(pMyPacketData, pPacketData, pkthdr.caplen);
   175          if (!rawPacket.setRawData(pMyPacketData, pkthdr.caplen, pkthdr.ts, static_cast<LinkLayerType>(m_PcapLinkLayerType), pkthdr.len))
   176          {
   177                  LOG_ERROR("Couldn't set data to raw packet");
   178                  return false;
   179          }
   180          m_NumOfPacketsRead++;
   181          return true;
   182  }
