   197  bool PcapNgFileReaderDevice::matchPacketWithFilter(const uint8_t* packetData, size_t packetLen, timespec packetTimestamp, uint16_t linkType)
   198  {
   199          if (m_CurFilter == "")
   200                  return true;
   201
   202          int linkTypeAsInt = (int)linkType;
   203
   204          if (m_BpfLinkType != linkTypeAsInt)
   205          {
   206                  LOG_DEBUG("Compiling the filter '%s' for link type %d", m_CurFilter.c_str(), linkTypeAsInt);
   207                  if (m_BpfInitialized)
   208                          pcap_freecode(&m_Bpf);
   209                  if (pcap_compile_nopcap(9000, linkTypeAsInt, &m_Bpf, m_CurFilter.c_str(), 1, 0) < 0)
   210                  {
   211                          m_BpfInitialized = false;
   212                          return false;
   213                  }
   214
   215                  m_BpfLinkType = linkTypeAsInt;
   216                  m_BpfInitialized = true;
   217          }
   218
   219          struct pcap_pkthdr pktHdr;
   220          pktHdr.caplen = packetLen;
   221          pktHdr.len = packetLen;
   222          TIMESPEC_TO_TIMEVAL(&pktHdr.ts, &packetTimestamp);
   223          return (pcap_offline_filter(&m_Bpf, &pktHdr, packetData) != 0);
   224  }
